// Node.js reading a file from a mounted network file system
// No special client library is needed, it looks exactly like local disk access
const fs = require('fs');

const data = fs.readFileSync('/mnt/uploads/invoice-1042.pdf');
console.log('read', data.length, 'bytes from the shared mount');

