// Application server handling an upload, using a normal local file write
const fs = require('fs');
const path = require('path');

app.post('/upload', (req, res) => {
  const dest = path.join('/mnt/uploads', req.file.originalname);
  fs.writeFileSync(dest, req.file.buffer);
  res.json({ status: 'saved', path: dest });
});

